def cache_sim(capacity, ttl, ops):
    from collections import OrderedDict

    cache = OrderedDict()  # {key: (value, write_time)}
    results = []

    for op in ops:
        if op[0] == 'put':
            _, t, key, value = op
            # Remove expired entries
            expired_keys = [k for k, (_, write_time) in cache.items() if t >= write_time + ttl]
            for k in expired_keys:
                del cache[k]

            # If key already exists, remove it first (to re-insert at end)
            if key in cache:
                del cache[key]
            # If cache is at capacity, evict LRU (first item)
            elif len(cache) >= capacity:
                cache.popitem(last=False)

            # Add the new entry
            cache[key] = (value, t)

        elif op[0] == 'get':
            _, t, key = op
            # Remove expired entries
            expired_keys = [k for k, (_, write_time) in cache.items() if t >= write_time + ttl]
            for k in expired_keys:
                del cache[k]

            if key in cache:
                value, _ = cache[key]
                # Move to end (most recently used)
                cache.move_to_end(key)
                results.append(value)
            else:
                results.append(-1)

    return results

